n = 16
word = ('aeiou' * ((n + 4) // 5))[:n]
last = {}
expected = 0
for index, character in enumerate(word):
    last[character] = index
    if len(last) == 5:
        expected += min(last.values()) + 1
case = {'word': word, 'k': 0}

